/**
 * Main proctoring engine — continuous client-side face detection, matching,
 * and phone/object detection.
 *
 * Uses @vladmandic/face-api (loaded globally) for face detection and
 * TensorFlow.js COCO-SSD (via object_detector module) for phone/object detection.
 *
 * Detection pipeline:
 * 1. Capture webcam stream
 * 2. Continuously detect faces using TinyFaceDetector (every 2s)
 * 3. Match detected face against student's profile picture descriptor
 * 4. Continuously detect prohibited objects using COCO-SSD (every 3s)
 * 5. Merge results and report violations to server via Moodle AJAX
 * 6. Display real-time status overlay on quiz page
 *
 * @module     quizaccess_proctor/proctoring
 * @package    quizaccess_proctor
 * @copyright  2026 Ayush Kannaujiya
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define(["core/ajax","core/notification","core/str","quizaccess_proctor/object_detector","quizaccess_proctor/gaze_tracker"],function(Ajax,Notification,Str,ObjectDetector,GazeTracker){let config={};let videoEl=null;let canvasEl=null;let stream=null;let referenceDescriptor=null;let modelsLoaded=false;let objectDetectorReady=false;let gazeTrackerReady=false;let isActive=false;let detectionTimer=null;let reportTimer=null;let resultBuffer=[];let lastViolationReportTime=0;let currentState={faceStatus:"active",confidence:0,objectViolation:false,worstObject:null,gazeViolation:false,gazeDirection:"center",gazeData:""};async function init(cfg){config=cfg;createOverlayUI();try{updateOverlayStatus("initializing","Starting camera...");await startWebcam();updateOverlayStatus("loading","Loading face detection models...");await loadModels();if(config.hasProfilePic&&config.profileImageUrl){updateOverlayStatus("loading","Analyzing profile picture...");await loadReferenceDescriptor()}else{updateOverlayStatus("warning","No profile picture — detection only")}if(config.objectDetectionEnabled){updateOverlayStatus("loading","Loading object detection model...");try{ObjectDetector.init(config).then(function(ready){objectDetectorReady=ready});GazeTracker.init(config).then(function(ready){gazeTrackerReady=ready});console.log("[Proctor] Object detection model loaded")}catch(objErr){console.warn("[Proctor] Object detection init error:",objErr);objectDetectorReady=false}}isActive=true;startDetectionLoop();startReportLoop();updateOverlayStatus("active","Proctoring active")}catch(err){console.error("[Proctor] Initialization failed:",err);updateOverlayStatus("error","Proctoring error: "+err.message)}}function createOverlayUI(){const overlay=document.createElement("div");overlay.id="proctor-overlay";overlay.className="proctor-overlay";overlay.innerHTML=`\n            <div class="proctor-overlay-header" id="proctor-overlay-header">\n                <span class="proctor-overlay-indicator" id="proctor-indicator"></span>\n                <span class="proctor-overlay-title" id="proctor-overlay-title">Proctoring</span>\n                <button class="proctor-overlay-toggle" id="proctor-toggle" title="Toggle camera preview">\n                    <span id="proctor-toggle-icon">▼</span>\n                </button>\n            </div>\n            <div class="proctor-overlay-body" id="proctor-overlay-body">\n                <div class="proctor-video-wrapper">\n                    <video id="proctor-video" autoplay muted playsinline></video>\n                    <canvas id="proctor-canvas" style="position:absolute;top:0;left:0;"></canvas>\n                </div>\n                <div class="proctor-overlay-status" id="proctor-status-text">Initializing...</div>\n            </div>\n            <div class="proctor-overlay-warning" id="proctor-warning" style="display:none;">\n                <span id="proctor-warning-text"></span>\n            </div>\n        `;document.body.appendChild(overlay);const toggleBtn=document.getElementById("proctor-toggle");const body=document.getElementById("proctor-overlay-body");const toggleIcon=document.getElementById("proctor-toggle-icon");let collapsed=false;toggleBtn.addEventListener("click",function(e){e.stopPropagation();collapsed=!collapsed;body.style.display=collapsed?"none":"block";toggleIcon.textContent=collapsed?"▶":"▼"});videoEl=document.getElementById("proctor-video");canvasEl=document.getElementById("proctor-canvas");const header=document.getElementById("proctor-overlay-header");let isDragging=false;let startX,startY,initialLeft,initialTop;header.addEventListener("mousedown",function(e){if(e.target.closest("#proctor-toggle"))return;isDragging=true;startX=e.clientX;startY=e.clientY;const rect=overlay.getBoundingClientRect();initialLeft=rect.left;initialTop=rect.top;overlay.style.right="auto";overlay.style.bottom="auto";overlay.style.left=initialLeft+"px";overlay.style.top=initialTop+"px";e.preventDefault()});document.addEventListener("mousemove",function(e){if(!isDragging)return;const dx=e.clientX-startX;const dy=e.clientY-startY;overlay.style.left=initialLeft+dx+"px";overlay.style.top=initialTop+dy+"px"});document.addEventListener("mouseup",function(){isDragging=false})}async function startWebcam(){try{stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:640},height:{ideal:480},facingMode:"user"},audio:false});videoEl.srcObject=stream;await videoEl.play();videoEl.width=videoEl.videoWidth||640;videoEl.height=videoEl.videoHeight||480;canvasEl.width=videoEl.videoWidth||640;canvasEl.height=videoEl.videoHeight||480}catch(err){throw new Error("Camera access denied. Please allow camera permissions.")}}async function loadModels(){if(typeof faceapi==="undefined"){throw new Error("face-api.js library not loaded")}const modelUrl=config.modelUrl;await Promise.all([faceapi.nets.tinyFaceDetector.loadFromUri(modelUrl),faceapi.nets.faceLandmark68Net.loadFromUri(modelUrl),faceapi.nets.faceRecognitionNet.loadFromUri(modelUrl)]);modelsLoaded=true}let profilePicFailed=false;async function loadReferenceDescriptor(){try{const img=await loadImage(config.profileImageUrl);const detection=await faceapi.detectSingleFace(img,new faceapi.TinyFaceDetectorOptions({inputSize:416,scoreThreshold:.1})).withFaceLandmarks().withFaceDescriptor();if(detection){referenceDescriptor=detection.descriptor;profilePicFailed=false;console.log("[Proctor] Reference descriptor loaded from profile picture")}else{console.warn("[Proctor] No face detected in profile picture");referenceDescriptor=null;profilePicFailed=true}}catch(err){console.error("[Proctor] Failed to load reference descriptor:",err);referenceDescriptor=null;profilePicFailed=true}}function loadImage(url){return new Promise(function(resolve,reject){const img=new Image;if(url.startsWith("http")&&!url.startsWith(window.location.origin)){img.crossOrigin="anonymous"}img.onload=function(){resolve(img)};img.onerror=function(){reject(new Error("Failed to load image: "+url))};img.src=url})}function startDetectionLoop(){const interval=config.captureInterval||2e3;async function detect(){if(!isActive||!modelsLoaded){return}try{await performDetection()}catch(err){console.error("[Proctor] Detection error:",err);currentState.status="error";updateOverlayFromState()}if(isActive){detectionTimer=setTimeout(detect,interval)}}detect()}async function performDetection(){if(!videoEl||videoEl.paused||videoEl.ended||!videoEl.videoWidth){return}const detections=await faceapi.detectAllFaces(videoEl,new faceapi.TinyFaceDetectorOptions({inputSize:416,scoreThreshold:.4})).withFaceLandmarks().withFaceDescriptors();drawDetections(detections);let status="no_face";let confidence=0;if(detections.length===0){status="no_face"}else if(detections.length>1){status="multiple_faces"}else{const faceDescriptor=detections[0].descriptor;if(referenceDescriptor){const distance=faceapi.euclideanDistance(faceDescriptor,referenceDescriptor);confidence=distance;const threshold=config.matchThreshold||.5;if(distance<threshold){status="match"}else{status="mismatch"}}else if(config.hasProfilePic&&profilePicFailed){status="error";confidence=-1}else{status="match";confidence=-1}}let objectResult={isViolation:false,detections:[],confirmedObjects:[]};if(objectDetectorReady){objectResult=await ObjectDetector.detect(videoEl)}let gazeResult={isViolation:false,direction:"center",gazeData:""};if(gazeTrackerReady){try{let gtState=await GazeTracker.analyze(videoEl);console.log("[Proctor Debug] GazeTracker.analyze returned:",gtState);gazeResult={isViolation:gtState.isViolation,direction:gtState.direction,gazeData:GazeTracker.formatForReport()}}catch(e){console.error("[Proctor] Gaze tracking error:",e)}}if(objectResult.isViolation){status="phone_detected"}else if(gazeResult.isViolation){status="looking_away"}currentState={faceStatus:status,confidence:confidence,objectViolation:objectResult.isViolation,worstObject:objectResult.confirmedObjects.length>0?objectResult.confirmedObjects[0]:null,gazeViolation:gazeResult.isViolation,gazeDirection:gazeResult.direction,gazeData:gazeResult.gazeData};let imageData="";if(status!=="match"){try{const tempCanvas=document.createElement("canvas");tempCanvas.width=320;tempCanvas.height=240;const tempCtx=tempCanvas.getContext("2d");tempCtx.drawImage(videoEl,0,0,320,240);imageData=tempCanvas.toDataURL("image/jpeg",.6)}catch(e){imageData=""}}resultBuffer.push({status:status,confidence:confidence,imageData:imageData,timestamp:Date.now(),objectsDetected:(objectResult.confirmedObjects||[]).join(","),gazeData:gazeResult.gazeData});updateOverlayFromState();if(status==="phone_detected"||status==="looking_away"){const now=Date.now();if(now-lastViolationReportTime>5e3){lastViolationReportTime=now;sendReport()}}}function drawDetections(detections){const displaySize={width:videoEl.offsetWidth||videoEl.videoWidth,height:videoEl.offsetHeight||videoEl.videoHeight};faceapi.matchDimensions(canvasEl,displaySize);const ctx=canvasEl.getContext("2d");ctx.clearRect(0,0,canvasEl.width,canvasEl.height);if(detections.length>0){const resized=faceapi.resizeResults(detections,displaySize);resized.forEach(function(det){const box=det.detection.box;const mirroredX=displaySize.width-box.x-box.width;const color=currentState.status==="match"?"#00e676":currentState.status==="mismatch"?"#ff1744":currentState.status==="multiple_faces"?"#ff9100":"#2979ff";ctx.strokeStyle=color;ctx.lineWidth=2;ctx.strokeRect(mirroredX,box.y,box.width,box.height);if(currentState.confidence>0){const threshold=config.matchThreshold||.5;const label=currentState.confidence<threshold?"✓ Dist: "+currentState.confidence.toFixed(2):"✗ Dist: "+currentState.confidence.toFixed(2);ctx.fillStyle=color;ctx.font="12px Inter, sans-serif";ctx.fillText(label,mirroredX,box.y-5)}})}if(objectDetectorReady){var objState=ObjectDetector.getState();if(objState.detections&&objState.detections.length>0){var scaleX=displaySize.width/(videoEl.videoWidth||640);var scaleY=displaySize.height/(videoEl.videoHeight||480);objState.detections.forEach(function(det){var bbox=det.bbox;var isConfirmed=objState.confirmedObjects.indexOf(det.class)!==-1;var objColor=isConfirmed?"#ff6d00":"#ffd600";var bx=bbox[0]*scaleX;var by=bbox[1]*scaleY;var bw=bbox[2]*scaleX;var bh=bbox[3]*scaleY;var mirroredObjX=displaySize.width-bx-bw;ctx.strokeStyle=objColor;ctx.lineWidth=isConfirmed?3:2;ctx.setLineDash(isConfirmed?[]:[6,3]);ctx.strokeRect(mirroredObjX,by,bw,bh);ctx.setLineDash([]);var label=ObjectDetector.getDisplayLabel(det.class)+" "+Math.round(det.score*100)+"%";ctx.fillStyle=objColor;ctx.font="bold 11px Inter, sans-serif";var labelWidth=ctx.measureText(label).width;ctx.fillRect(mirroredObjX,by-16,labelWidth+8,16);ctx.fillStyle="#000";ctx.fillText(label,mirroredObjX+4,by-4)})}}}function startReportLoop(){const interval=config.reportInterval||15e3;reportTimer=setInterval(function(){if(!isActive||resultBuffer.length===0){return}sendReport()},interval)}function sendReport(){if(resultBuffer.length===0){return}const priorityOrder=["phone_detected","looking_away","mismatch","multiple_faces","no_face","error","match"];let worstResult=resultBuffer[0];let allObjects=[];resultBuffer.forEach(function(r){if(r.objectsDetected){r.objectsDetected.split(",").forEach(function(obj){const trimmed=obj.trim();if(trimmed&&allObjects.indexOf(trimmed)===-1){allObjects.push(trimmed)}})}const currentPriority=priorityOrder.indexOf(r.status);const worstPriority=priorityOrder.indexOf(worstResult.status);if(currentPriority<worstPriority){worstResult=r}});if(allObjects.length>0&&!worstResult.objectsDetected){worstResult.objectsDetected=allObjects.join(",")}let imageData=worstResult.imageData||"";if(!imageData){for(let i=0;i<resultBuffer.length;i++){if(resultBuffer[i].imageData){imageData=resultBuffer[i].imageData;break}}}resultBuffer=[];if(worstResult.status==="match"){return}Ajax.call([{methodname:"quizaccess_proctor_store_snapshot",args:{attemptid:config.attemptId,quizid:config.quizId,courseid:config.courseId,status:worstResult.status,confidence:worstResult.confidence>=0?worstResult.confidence:0,imagedata:imageData,objectsdetected:worstResult.objectsDetected||"",gazedata:worstResult.gazeData||"",timestamp:Math.floor((worstResult.timestamp||Date.now())/1e3)}}])[0].then(function(result){if(result.success){console.log("[Proctor] Violation report sent, logId:",result.logid,"status:",worstResult.status,"objects:",worstResult.objectsDetected)}}).catch(function(err){console.error("[Proctor] Failed to send report:",err)})}function updateOverlayFromState(){const indicator=document.getElementById("proctor-indicator");const statusText=document.getElementById("proctor-status-text");const title=document.getElementById("proctor-overlay-title");const warning=document.getElementById("proctor-warning");const warningText=document.getElementById("proctor-warning-text");if(!indicator||!statusText){return}switch(currentState.faceStatus){case"match":indicator.className="proctor-overlay-indicator proctor-status-match";statusText.textContent="Identity verified";title.textContent="Proctoring ✓";hideWarning();break;case"mismatch":indicator.className="proctor-overlay-indicator proctor-status-mismatch";statusText.textContent="Face mismatch (distance: "+currentState.confidence.toFixed(3)+")";title.textContent="Proctoring ⚠";showWarning("Face does not match your profile picture. Please ensure you are the registered student.");break;case"no_face":indicator.className="proctor-overlay-indicator proctor-status-warning";statusText.textContent="No face detected";title.textContent="Proctoring ⚠";showWarning("No face detected — please look at the camera.");break;case"multiple_faces":indicator.className="proctor-overlay-indicator proctor-status-mismatch";statusText.textContent="Multiple faces detected";title.textContent="Proctoring ⚠";showWarning("Multiple faces detected — only one person should be visible.");break;case"phone_detected":indicator.className="proctor-overlay-indicator proctor-status-phone";statusText.textContent="Prohibited object detected";title.textContent="Proctoring ⚠";showWarning("Prohibited object detected — please don't use unfair means.");break;case"looking_away":indicator.className="proctor-overlay-indicator proctor-status-gaze";statusText.textContent="Looking away from screen";title.textContent="Proctoring ⚠";showWarning("Please look at the screen. Gaze tracking active.");break;case"error":indicator.className="proctor-overlay-indicator proctor-status-error";statusText.textContent="Detection error";title.textContent="Proctoring ✗";break;default:indicator.className="proctor-overlay-indicator proctor-status-loading";statusText.textContent="Initializing..."}function showWarning(message){if(warning&&warningText){warning.style.display="block";warningText.textContent=message;setTimeout(function(){if(warning){warning.style.display="none"}},5e3)}}function hideWarning(){if(warning){warning.style.display="none"}}}function updateOverlayStatus(status,message){const indicator=document.getElementById("proctor-indicator");const statusText=document.getElementById("proctor-status-text");const title=document.getElementById("proctor-overlay-title");if(!indicator||!statusText){return}statusText.textContent=message;switch(status){case"active":indicator.className="proctor-overlay-indicator proctor-status-match";title.textContent="Proctoring ✓";break;case"warning":indicator.className="proctor-overlay-indicator proctor-status-warning";title.textContent="Proctoring ⚠";break;case"error":indicator.className="proctor-overlay-indicator proctor-status-error";title.textContent="Proctoring ✗";break;default:indicator.className="proctor-overlay-indicator proctor-status-loading";title.textContent="Proctoring..."}}function stop(){isActive=false;if(detectionTimer){clearTimeout(detectionTimer);detectionTimer=null}if(reportTimer){clearInterval(reportTimer);reportTimer=null}ObjectDetector.stop();if(resultBuffer.length>0){sendReport()}if(stream){stream.getTracks().forEach(function(track){track.stop()});stream=null}}window.addEventListener("beforeunload",function(){stop()});return{init:init,stop:stop}});